uniform float amzp_chromaShrink;
uniform float amzp_unsharpAmount;
uniform float amzp_unsharpRadius;
uniform float amzp_unsharpThreshold;
uniform float amzp_blackLevel;
uniform float amzp_whiteLevel;
uniform float amzp_saturation;
layout(color) uniform half4 amzp_shadowTint;
uniform float amzp_sourceFps;
uniform float amzp_lineHeight;
uniform float amzp_noiseGrain;
uniform float amzp_noiseBlend;
uniform float amzp_trackingSpeed;
uniform float amzp_trackingOffset;
uniform float amzp_trackingJitter;
uniform float amzp_waveFreq;
uniform float amzp_waveOffset;
uniform float amzp_bottomWarpH;
uniform float amzp_bottomWarpOff;
