    float4 warpBottom(float height, float offset, float jitter, float2 uv){ float h = height / screen.zw.y; if(uv.y > h) return sample(uv); float t = uv.y / h; float off = t * (offset / screen.zw.x); float j = (gold(float2(500.0,500.0), fract(time)) * jitter) / screen.zw.x; float2 u = float2(uv.x - off - j, uv.y); float4 px = sample(u); return px * t; }
    float4 whiteNoise(float thick, float opac, float4 px, float2 fragCoord){ if(gold(float2(600.0,500.0), fract(time) * 10.0) > 0.97){ float start = floor(gold(float2(800.0,50.0), fract(time)) * screen.zw.y); float endv = floor(start + thick); if(floor(fragCoord.y) >= start && floor(fragCoord.y) < endv){ float freq = gold(float2(850.0,50.0), fract(time)) * 3.0 + 1.0; float off = gold(float2(900.0,51.0), fract(time)); float x = floor(fragCoord.x) / floor(screen.zw.x) + off; float w = pow(cos(PI * fract(x * freq) / 2.0), 10.0) * opac; float grit = gold(float2(floor(fragCoord.x / 3.0), 800.0), fract(time)); w = max(w - grit * 0.3, 0.0); return px + w; } } return px; }

