      uv = waveUV(amzp_waveFreq, amzp_waveOffset, fragCoord, uv);
      float4 luma = shrink(fragCoord, amzp_lumaShrink);
      luma = blendLum(float4(0.5,0.5,0.5,1.0), luma);
      float4 chroma = shrink(fragCoord, amzp_chromaShrink);
      chroma = blendColor(luma, chroma);
