      pixel = mix(pixel, float4(0.0,0.0,0.0,1.0), 1.0 - amzp_whiteLevel);
      float3 inten = float3(dot(pixel.rgb, W));
      pixel = float4(mix(inten, pixel.rgb, amzp_saturation), 1.0);
