      grain = float4(r,g,b,1.0);
      noisePx = soft4(noisePx, grain) * amzp_noiseBlend + noisePx * (1.0 - amzp_noiseBlend);
      float4 warped = warpBottom(amzp_bottomWarpH, amzp_bottomWarpOff, amzp_bottomWarpJit, uv);
      float4 outPx = noisePx;
      outPx = whiteNoise(amzp_noiseLineThick, amzp_noiseLineOpac, outPx, fragCoord);
      float vign = pow(uv.x * (1.0 - uv.x) * uv.y * (1.0 - uv.y), 0.25) * 2.2;
      outPx *= vign;
      amzOutput = outPx;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
